//! Files written by Blender 5.2.4's own writers (`tests/data/blender/`, generated by
//! `tests/data/make_blender_fixtures.py`) decode to the pattern Blender was given.

use frap_imbuf::{FileFormat, PixelData, decode};
use serde_json::Value;

const DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/data/blender");

struct Expected {
    w: u32,
    h: u32,
    bytes: Vec<[u8; 4]>,
    floats: Vec<[f32; 4]>,
}

fn expected() -> Expected {
    let v: Value =
        serde_json::from_str(&std::fs::read_to_string(format!("{DIR}/expected.json")).unwrap())
            .unwrap();
    let arr4 = |p: &Value| -> [f64; 4] {
        let a = p.as_array().unwrap();
        [0, 1, 2, 3].map(|i| a[i].as_f64().unwrap())
    };
    Expected {
        w: v["width"].as_u64().unwrap() as u32,
        h: v["height"].as_u64().unwrap() as u32,
        bytes: v["byte_rgba"]
            .as_array()
            .unwrap()
            .iter()
            .map(|p| arr4(p).map(|x| x as u8))
            .collect(),
        floats: v["float_rgba"]
            .as_array()
            .unwrap()
            .iter()
            .map(|p| arr4(p).map(|x| x as f32))
            .collect(),
    }
}

fn load(name: &str) -> frap_imbuf::DecodedImage {
    let bytes = std::fs::read(format!("{DIR}/{name}")).unwrap();
    let img = decode(&bytes).unwrap_or_else(|e| panic!("{name}: {e}"));
    let e = expected();
    assert_eq!((img.width, img.height), (e.w, e.h), "{name}");
    img
}

#[test]
fn lossless_byte_formats_match_exactly() {
    let e = expected();
    for name in ["png8.png", "tga.tga", "webp.webp"] {
        let img = load(name);
        assert_eq!(img.channels, 4, "{name}");
        let want: Vec<u8> = e.bytes.iter().flatten().copied().collect();
        assert_eq!(img.pixels, PixelData::U8(want), "{name}");
    }
}

#[test]
fn rgb_byte_formats_match_on_opaque_pixels() {
    // color_mode='RGB' composites over black first (IMB_alpha_under_color_byte), so only
    // opaque pixels keep the input values.
    let e = expected();
    let img = load("bmp.bmp");
    assert_eq!(img.channels, 3);
    let got = img.to_u8();
    for (i, p) in e.bytes.iter().enumerate() {
        if p[3] == 255 {
            assert_eq!(&got[3 * i..3 * i + 3], &p[..3], "bmp pixel {i}");
        }
    }
    // JPEG (quality 100) subsamples chroma, so on this noisy pattern only the luma (BT.601 Y,
    // stored at full resolution) is compared.
    let img = load("jpeg.jpg");
    assert_eq!(img.channels, 3);
    let got = img.to_u8();
    let y = |c: &[u8]| 0.299 * f32::from(c[0]) + 0.587 * f32::from(c[1]) + 0.114 * f32::from(c[2]);
    for (i, p) in e.bytes.iter().enumerate() {
        if p[3] == 255 {
            let (g, w) = (y(&got[3 * i..3 * i + 3]), y(&p[..3]));
            assert!((g - w).abs() <= 4.0, "jpeg pixel {i}: luma {g} vs {w}");
        }
    }
}

#[test]
fn png16_matches_on_opaque_pixels() {
    let e = expected();
    let img = load("png16.png");
    assert_eq!(img.channels, 4);
    let PixelData::U16(got) = &img.pixels else {
        panic!("png16 must decode as 16-bit");
    };
    for (i, p) in e.bytes.iter().enumerate() {
        if p[3] == 255 {
            for k in 0..4 {
                assert_eq!(got[4 * i + k], u16::from(p[k]) * 257, "pixel {i}");
            }
        }
    }
}

#[test]
fn exr_matches_float_and_half() {
    let e = expected();
    let full: Vec<f32> = e.floats.iter().flatten().copied().collect();
    let img = load("exr_float.exr");
    assert_eq!(
        FileFormat::detect(&std::fs::read(format!("{DIR}/exr_float.exr")).unwrap()),
        Some(FileFormat::OpenExr)
    );
    assert_eq!(img.channels, 4);
    assert_eq!(img.pixels, PixelData::F32(full.clone()));
    let half = load("exr_half.exr");
    let want: Vec<f32> = full
        .iter()
        .map(|v| half::f16::from_f32(*v).to_f32())
        .collect();
    assert_eq!(half.pixels, PixelData::F32(want));
}

#[test]
fn hdr_matches_within_rgbe_precision() {
    let e = expected();
    let img = load("hdr.hdr");
    assert_eq!(img.channels, 3);
    let got = img.to_f32();
    for (i, p) in e.floats.iter().enumerate() {
        let max = p[0].max(p[1]).max(p[2]);
        for k in 0..3 {
            let g = got[3 * i + k];
            assert!(
                (g - p[k]).abs() <= max / 128.0,
                "pixel {i}: {g} vs {}",
                p[k]
            );
        }
    }
}
